import{_ as e,o as t,c as a,a4 as _}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"减油增豆加奶　助力全民健康——对话王瑛瑶、刘爱玲、程广燕、朱文丽2026-04-29","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"减油增豆加奶　助力全民健康——对话王瑛瑶、刘爱玲、程广燕、朱文丽2026-04-29","date":"2026-04-29T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202604/t20260429_6483791.htm","summary":"主持人　农民日报全媒体记者　赵新宁\\n王瑛瑶　　中国营养学会副秘书长\\n刘爱玲　　中国疾病预防控制中心营养与健康所副所长\\n程广燕　　农业农村部食物与营养发展研究所食物节约减损与绿色消费团队首席\\n朱文丽　　北京大学公共卫生学院营养与食品卫生学系教授\\n“减油、增豆、加奶”要融入一日三餐，关键在于总量达标，学会替换。科学饮食从来不是苛刻的自我约束，而是用更合理的搭配，兼顾味蕾享受与身体健康。\\n...\\n","contentHash":"3482e2267d9883a534e6c4fe71ede8e5","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-04-29-减油增豆加奶-助力全民健康-对话王瑛瑶-刘爱玲-程广燕-朱文丽.md","filePath":"policies/2026-04-29-减油增豆加奶-助力全民健康-对话王瑛瑶-刘爱玲-程广燕-朱文丽.md"}'),s={name:"policies/2026-04-29-减油增豆加奶-助力全民健康-对话王瑛瑶-刘爱玲-程广燕-朱文丽.md"};function r(o,p,n,l,c,i){return t(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="减油增豆加奶-助力全民健康——对话王瑛瑶、刘爱玲、程广燕、朱文丽2026-04-29" tabindex="-1">减油增豆加奶　助力全民健康——对话王瑛瑶、刘爱玲、程广燕、朱文丽2026-04-29 <a class="header-anchor" href="#减油增豆加奶-助力全民健康——对话王瑛瑶、刘爱玲、程广燕、朱文丽2026-04-29" aria-label="Permalink to &quot;减油增豆加奶　助力全民健康——对话王瑛瑶、刘爱玲、程广燕、朱文丽2026-04-29&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202604/t20260429_6483791.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-04-29 摘要: 主持人　农民日报全媒体记者　赵新宁 王瑛瑶　　中国营养学会副秘书长 刘爱玲　　中国疾病预防控制中心营养与健康所副所长 程广燕　　农业农村部食物与营养发展研究所食物节约减损与绿色消费团队首席 朱文丽　　北京大学公共卫生学院营养与食品卫生学系教授 “减油、增豆、加奶”要融入一日三餐，关键在于总量达标，学会替换。科学饮食从来不是苛刻的自我约束，而是用更合理的搭配，兼顾味蕾享受与身体健康。 ...</p></blockquote><p>“减油、增豆、加奶”要融入一日三餐，关键在于总量达标，学会替换。科学饮食从来不是苛刻的自我约束，而是用更合理的搭配，兼顾味蕾享受与身体健康。</p><p>营养是维持生命、生长发育和健康的重要物质基础，国民营养事关国民素质提高和经济社会发展。2024年，国民营养健康指导委员会办公室曾印发“减油、增豆、加奶”核心信息，倡导全民树立健康饮食新风尚。当前，我国居民仍面临营养不足与过剩并存、营养相关疾病多发的问题，油、豆、奶的摄入现状与推荐标准存在明显差距。“减油、增豆、加奶”的现实条件怎样？这样吃有什么好处？如何让更多人接受这一饮食新风尚？本期《对话》邀请王瑛瑶、刘爱玲、程广燕、朱文丽四位专家展开交流讨论。</p><p>朱文丽：《中国居民膳食指南（2022）》将多吃奶、大豆及其制品作为核心推荐内容之一，建议成年人平均每天摄入300毫升以上液体奶或相当量的奶制品，以及15～25克大豆或相当量的大豆制品。《中国居民营养与慢性病状况报告（2020年）》显示，我国居民每标准人每天奶及奶制品的摄入量仅为25.9克，未达到推荐摄入量的十分之一；大豆及其制品的摄入量为10.3克，超过三分之二的居民未达到推荐量。与奶、豆摄入不足相对应的是，《中国居民膳食指南（2022）》推荐的成年人每天烹调油摄入量不超过25～30克，而《中国居民营养与慢性病状况报告（2020年）》显示，我国居民每标准人每天的烹调油摄入量高达43.2克，已超出推荐量的三分之一。</p><p>刘爱玲：造成“一多两少”的原因是多方面的。一是公众的健康意识仍不强，选择食物仍更注重口感、口味，如油多菜香，不喜欢豆制品的味道。二是关于大豆制品和奶制品的认知误区普遍存在，如不少人认为吃大豆制品易造成性早熟、喝奶容易得结石等。三是多数人未养成每日饮奶习惯，消费形式单一。</p><p>王瑛瑶：我国居民在奶、豆、油膳食摄入上普遍存在不合理，主要原因有几个方面。一是合理膳食行动和实践有待提升。吃是人类的本能，但吃与会吃、吃得健康有本质区别。居民对于如何科学选油用油、奶和豆在膳食中重要性的认知亟待加强。二是饮食惯性和营养认知误区普遍存在。诸如，从昔日缺油少粮到如今油水充足的转变过程中，形成了“油多菜香”的烹饪习惯；豆制品处于配菜地位，消费量受限；饮奶习惯尚未在全社会普遍养成；对过量油脂摄入的危害，以及对大豆、奶类的营养价值认知不足。三是产业供给结构中，大豆加工长期以压榨制油为主，食品加工占比偏低；奶制品结构较为单一，适合中国人口味和消化特点的产品开发不足。</p><p>王瑛瑶：具体而言，“减油、增豆、加奶”为乡村振兴和健康中国建设注入三大动力。第一，推动农业供给侧结构性改革。减少不合理的油脂消费，可以缓解我国食用油对外依存度较高的压力。增加大豆和奶类消费，将直接带动大豆种植业和奶业发展，从源头刺激大豆和奶业精深加工链条延长和技术布局提升。</p><p>第二，构建“合理膳食-提升国民健康-促进产业发展”良性循环。合理膳食理念的普及有利于推进“减油、增豆、加奶”的实现，提升国民健康水平，减少不合理膳食相关的慢性疾病医疗支出。饮食需求的增长又会促进奶、豆、油相关产业发展，有效带动种植、养殖、加工、物流、销售等环节，促进乡村产业融合发展。</p><p>第三，助力粮食安全战略。我国大豆是国民直接消费的优质蛋白和食用油脂、饲料来源，提高居民直接食用大豆及其制品消费量，可以在一定程度上减少资源对外依赖。</p><p>程广燕：“减油、增豆、加奶”既是膳食优化路径，更是农业结构调整与乡村振兴的重要抓手。从食物供给端看，减少过量油脂消费，能减轻油料作物进口压力，稳定食物安全基本盘；扩大大豆生产，能提升国产大豆自给能力，发挥其固氮养地优势，改善耕地质量，实现生态与生产双赢；发展奶业则能充分利用秸秆、饲草等资源，推动农牧循环，拓展农业增值空间。</p><p>从国民健康与产业发展的关系看，引导居民科学减油、多吃豆制品、增加奶类摄入，既能降低慢性病风险，夯实健康中国根基，又能倒逼农业向优质、多元转型，带动种植、养殖、加工、冷链物流全链条升级。这一模式让田间生产与餐桌需求精准对接，促进农民增收、产业增效，真正把营养健康需求转化为乡村产业发展动能，实现食物安全、国民健康与乡村振兴协同推进。</p><p>王瑛瑶：改变“油多味香”这一观念需要从认知、工具、烹饪技巧等多方面入手。</p><p>第一，培养健康饮食习惯。健康与美味并非对立关系，过量用油不仅增加慢性病风险，还会掩盖食材本身的风味。第二，树立科学用油观念。“减油”的核心是控量而非禁食，建议成年人每天烹饪油摄入量不超过30克。第三，科学选油。不同烹饪方式选择不同油品。高温煎炸可选烟点高的花生油、稻米油；凉拌可选亚麻籽油、油茶籽油；日常炒菜可用大豆油、菜籽油。还要控制油温，避免油温过高产生有害物质。采取热锅凉油、少油蒸炖的方式，既能保持营养，又能减少用油量。</p><p>朱文丽：需要强调的是，“油多味香”并不是认知误区，食物中的脂肪本就有改善食物感官性状的作用，富含脂肪的食物吃起来比较香。但是，如前所述，长期过量摄入脂肪会导致肥胖，增加血脂异常、动脉粥样硬化、冠心病和2型糖尿病等慢性病的发病风险。因此，我们在选择食物时要兼顾美味可口与健康需求。</p><p>减少家庭烹饪用油是实现“减油”的重要环节。家庭烹饪可使用带刻度的控油壶，定量用油，控制总量。尽量选择蒸、煮等烹调方法，少煎炸。此外，也可使用不粘锅、空气炸锅等，减少烹调油的用量。多样化的用油选择有利于营养平衡，如橄榄油、茶油的单不饱和脂肪酸含量较高，玉米油、葵花籽油则富含亚油酸，亚麻籽油中富含α-亚麻酸。经常更换不同品种的烹调油，可以为脂肪酸和营养的均衡摄入提供保障。</p><p>朱文丽：对于消费端的居民而言，一日三餐可选择不同的大豆及其制品，包括豆腐、豆腐干、豆浆等。既变换口味，又能满足营养需求。尤其目前我国居民畜肉摄入过多，可用大豆及其制品替换部分肉类，既保证了优质蛋白质摄入，又可降低因摄入过多畜肉而引起的健康风险。对于高血压、高血脂、2型糖尿病、心血管疾病等人群，如果没有饮食禁忌，均可在一般人群推荐量基础上，适当增加大豆及其制品的摄入。豆腐、豆干等豆制品在加工后嘌呤含量也有所降低，高尿酸血症人群及痛风患者也可适量食用。</p><p>此外，在烹制和食用大豆及其制品时，应注意少放油、盐、糖。购买预包装大豆制品时，要注意查看营养成分表，尽量选择脂肪、钠含量较低的产品。有些大豆制品因制作工艺需要，制作过程中会添加较多的盐、油或糖，如腐乳、豆豉、豆瓣酱等，要注重适量食用。</p><p>王瑛瑶：提升大豆及其制品消费需要生产、加工、消费三端协同发力，构建“需求牵引供给、供给创造需求”的良性循环。</p><p>在生产端，要优化品种结构，提升原料品质。加大营养导向型农业投入力度，针对不同加工和营养需求，培育高蛋白、高异黄酮等功能性大豆品种。</p><p>在加工端，要推动技术创新和产品升级。一方面，提升大豆增值加工技术，做到“吃干用尽”。通过低温制油技术，确保榨油后的豆粕保留较高的蛋白利用价值；开发大豆膳食纤维、大豆磷脂、功能性固体饮料等相关产品。另一方面，实现大豆及其制品的产品及形态创新，开发适合不同人群、不同健康需求的即食、便携产品，让产品能触达更多消费者。</p><p>在消费端，加强营养教育和多样化消费场景拓展。加强对《中国居民膳食指南》的全民宣传和教育，让消费者明确大豆及其制品在膳食中的重要性。实施“国产大豆消费行动”，通过传统食材烹饪比赛、产品创新大赛等方式，充分发挥全民智慧，开发大豆及其制品的多样化消费。</p><p>朱文丽：奶及奶制品种类丰富，常见的有液态奶、酸奶、奶酪、奶粉等。与液态奶相比，酸奶、奶酪等风味不同，可以多尝试，丰富食物多样性。运输不便的地区，则可以选择奶粉、奶酪等更容易贮存的产品。除牛奶外，羊奶、马奶、驼奶等也是奶及奶制品的重要组成，居民可根据需要选择。奶及奶制品除直接食用外，还可以在烘焙、炖煮等烹饪过程中添加，为各种食品和菜肴增添独特的风味和营养。比如，牛奶可以加入到咖啡中，提升口感；酸奶则可以作为酱料加入沙拉中。乳糖不耐受人群可选择无乳糖、低乳糖奶或酸奶、奶酪等发酵乳制品；超重肥胖、高血脂人群可选择脱脂奶或低脂奶。</p><p>程广燕：扩大奶类消费，必须坚持问题导向和系统思维，统筹扩大内需和深化供给侧结构性改革，多途径、多主体、多措施、全产业链合力推进。一是扩大“学生饮用奶”推广规模，培育壮大奶类消费群体。二是打造一批以奶制品为主料的网红食品、菜品和饮品，将奶类融入国人餐饮习惯。三是推动乳品加工业供给侧结构性改革，强化产业链韧性。四是完善奶业产需平衡宏观调控机制，避免奶业发展大起大落。</p><p>刘爱玲：“减油、增豆、加奶”要融入一日三餐，关键在于总量达标，学会替换。对于烹调油来说，要做到全天控量，每餐都要减少用量。豆腐、豆浆、豆腐脑等大豆制品可以轮换食用，既变换口味，又能满足营养需求。奶制品和大豆制品可以在餐次间调整，如早餐喝豆浆或豆腐脑，那奶制品就放在午餐或晚餐，或者作为零食。其实日常饮食践行减油、增豆、加奶并没有大家想得那么难，关键还是有意识，健康饮食也从来不是苛刻的自我约束，而是用更合理的搭配，兼顾味蕾享受与身体健康。</p><p>程广燕：要让方案落地见效，就要融入一日三餐、贴合国人饮食习惯，做到简单易行、长期可坚持。同时，要把膳食指导与本地饮食特色结合起来，鼓励各地开发本土化、家常化的搭配方案，让减油不寡淡、增豆不单调、加奶更方便。此外，从居民食物消费的长期趋势看，奶类是我国居民主要食物消费中最突出的短板产品，也是未来增长潜力最大的朝阳产品。应联动生产端与消费端，引导农户发展优质大豆、奶源基地，实现健康食材就近供给、价格亲民，真正把营养方案变成餐桌常态。</p><p>王瑛瑶：从营养科学与公共卫生视角来看，“减油、增豆、加奶”三者协同发力，是构建平衡膳食模式、改善国民营养健康状况的关键举措。减油是控制能量过剩、降低慢性疾病风险的基础，增豆与加奶则是补齐优质蛋白、钙质及多种微量营养素短板的重要途径，三者互为支撑、缺一不可。</p><p>在日常落地中，应遵循“控油为基、豆奶互补、三餐贯穿”的原则，将营养目标转化为简单可执行的膳食行为。同时，这一搭配模式也为食物产业升级提供了清晰方向，能够引导食品加工、餐饮供给向健康化、轻量化、营养化转型。通过将营养标准融入食材生产、产品研发与餐饮规范，推动形成从田头到餐桌的全链条健康支撑体系。</p><p>朱文丽：针对不同人群实施“减油、增豆、加奶”，既要兼顾营养需求，也要贴合生活场景，突出可操作性与可持续性。对于农村居民，重点要改变高油烹饪习惯，结合本地食材，推广豆制品家常菜，利用村集体、合作社等渠道，让平价奶、常温奶更易获取，降低消费门槛。对于儿童青少年，可将豆奶、牛奶搭配纳入其日常加餐，用豆制品替代部分油炸零食，在校园和家庭中同步营造清淡饮食氛围。对于老年人，侧重研发和推广易消化、好吸收的豆制品与奶制品，如嫩豆腐、酸奶、配方奶等，在减油上强调少煎炒、多炖煮。此外，还应加强家庭与社区联动，把营养知识转化为简单易行的膳食口诀和搭配范例，让不同人群都能轻松坚持。</p><p>刘爱玲：农村居民、老年人、儿童青少年等群体的膳食状况和健康需求不同，推进“减油、增豆、加奶”需坚持因人因地施策。</p><p>针对农村居民，重点在于工具普及与习惯转变。可提供控油壶等工具，推广水油焖等少油烹饪方式，加大奶制品和大豆制品的供应，帮助他们改变高油、不喝奶等习惯。鼓励有条件的地区种植大豆，延续“豆子换豆腐”等传统模式。鼓励农村的超市、小卖部、集市以及商户售卖奶制品和大豆制品。</p><p>针对老年人，重在破除认知误区、提升膳食适口性。鼓励老年人每日都要摄入充足的奶制品和大豆制品。老年人味觉减退，做菜会加入更多的油盐，建议烹饪时多搭配葱姜蒜、番茄、菌菇等食材，避免菜品寡淡影响食欲。</p><p>针对儿童青少年，应从趣味引导与环境营造发力。通过健康教育课、小菜园、食堂帮厨等多种形式，普及营养知识；将“减油、增豆、加奶”融入校园餐，加强食堂人员培训，研制低油菜品，减少烹调油使用；丰富大豆制品的菜品，如家常豆腐、芹菜炒豆干、腐竹炒木耳等；增加奶制品供应，如一盒牛奶作为课间加餐，或午餐提供一份酸奶等。</p><p>程广燕：将“减油、增豆、加奶”纳入国民营养行动，需从政策供给、产业扶持、标准引领三方面精准发力。政策上，要强化顶层设计，完善大豆、油料、奶业的产能提升与补贴政策，扩大优质健康食材供给。产业上，农业农村、工信等部门联动，支持大豆精深加工，以及低脂健康油品、低温乳制品等产品研发，培育营养健康食品产业集群。标准上，加快修订食用油、豆制品、乳制品的营养标准，推行营养标签规范化，引导企业生产健康化产品。</p><p>推动科普与产业融合，要建立“政策引导-企业参与-科普落地”机制。依托全民营养周等活动，鼓励龙头企业开发科普产品，将营养知识融入食材生产、加工、消费全链条。同时，建设营养健康食堂、餐厅，打造示范场景，让健康理念转化为消费习惯，实现民生改善与产业升级互促共赢。</p><p>朱文丽：推动“减油、增豆、加奶”落地，科普与产业深度融合是关键，需精准科普、场景赋能、市场激励协同发力。科普层面，要构建分层分类体系，针对农村、社区、学校等不同场景，开发通俗易懂、接地气的科普内容，用图文、短视频、实操指南等形式，让科学用油、吃豆喝奶的知识入脑入心。产业层面，引导企业以需求为导向，开发低脂油、即食豆制品、平价常温奶等亲民产品，降低健康食材消费门槛。</p><p>要创新融合模式，支持企业参与科普公益活动，打造“科普+产品+体验”一体化场景。在商超、社区设立健康膳食体验区，开展烹饪演示、搭配指导，让消费者直观感受健康方案的可行性。同时，完善激励机制，对科普成效显著、产品优质的企业给予政策倾斜，形成“科普提认知、认知促消费、消费兴产业”的良性循环，让国民营养行动真正落地生根、惠及全民。</p><p><a href="https://scs.moa.gov.cn/gzdt/202604/t20260429_6483791.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',38)])])}const m=e(s,[["render",r]]);export{f as __pageData,m as default};
